import type { ComponentProps, MouseEvent, ReactNode } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Tag.module.css'

/** Status first, then every hue the accent ramps offer, for categories. */
export const TAG_VARIANTS = [
  'neutral',
  'info',
  'success',
  'warning',
  'danger',
  'red',
  'orange',
  'amber',
  'yellow',
  'lime',
  'green',
  'emerald',
  'teal',
  'cyan',
  'sky',
  'blue',
  'indigo',
  'violet',
  'purple',
  'fuchsia',
  'pink',
  'rose',
] as const
export type TagVariant = (typeof TAG_VARIANTS)[number]

export interface TagProps extends Omit<ComponentProps<'span'>, 'children'> {
  text: string
  startIcon?: ReactNode
  /** Image URL for a small avatar before the text, e.g. a person in a filter. */
  startAvatar?: string
  /**
   * One size: every tag is 20px tall.
   * @deprecated `sm` renders the same tag as `md` and warns in development; `md`, the default, is
   * silent. The prop goes in the next release: drop it.
   */
  size?: 'sm' | 'md'
  appearance?: 'subtle' | 'outlined' | 'solid'
  variant?: TagVariant
  hasRemoveButton?: boolean
  onRemove?: (event: MouseEvent<HTMLButtonElement>) => void
}

let hasWarned = false

export function Tag({
  text,
  startIcon,
  startAvatar,
  size = 'md',
  appearance = 'subtle',
  variant = 'info',
  hasRemoveButton = false,
  onRemove,
  className,
  ...props
}: TagProps) {
  if (import.meta.env.DEV && !hasWarned && size === 'sm') {
    hasWarned = true
    console.warn('Tag: `size="sm"` is deprecated and renders as `md`. `size` will be removed in the next release.')
  }
  return (
    <span
      className={cn(
        styles.tag,
        styles[appearance],
        styles[variant],
        className,
      )}
      {...props}
    >
      {startAvatar ? (
        // A plain image, not <Avatar>: the tag only needs a round crop, and a
        // cross-component import would not survive the copy-source install.
        <img src={startAvatar} alt="" className={styles.avatar} />
      ) : (
        startIcon && (
          <span className={styles.icon} aria-hidden="true">
            {startIcon}
          </span>
        )
      )}
      <span className={styles.text}>{text}</span>
      {hasRemoveButton && (
        <button
          type="button"
          // "Remove" alone is ambiguous in a list of tags, each with its own.
          aria-label={`Remove ${text}`}
          className={styles.remove}
          onClick={onRemove}
        >
          <Icon name="close" />
        </button>
      )}
    </span>
  )
}

/* One size, Atlassian's tag: 20px tall (control tier xs, see
   Foundations/Sizing), 12/16 text, 4px from the outer edge to the content
   (Atlassian's 3px padding inside a 1px border, so the padding here is
   --space-1 less --border-width), and no wider than 180px before the text
   ellipsizes. The corner is the tier's, 4px, and
   follows the Theme's radius preset like every control: a pill under
   radius="full-rounded". The border is always there (transparent unless
   outlined) so appearances never shift the layout. */
.tag {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- 180px, Atlassian's cap for a tag; no size token is that wide */
  max-inline-size: min(100%, 11.25rem);
  block-size: var(--control-xs);
  box-sizing: border-box;
  padding-inline: calc(var(--space-1) - var(--border-width));
  border: var(--border-width) solid transparent;
  border-radius: var(--control-xs-radius);
  white-space: nowrap;
  /* Every digit takes the same width, so a tag holding a live count or a
     countdown keeps its width as the number changes. */
  font-variant-numeric: tabular-nums;
}

/* In a line of text the tag is centred on that line, whatever its font.
   Not `vertical-align: middle`: that centres on the text's x-height, a
   pixel under the line's own centre, so a 20px tag made a 20px line 21px
   (and a 28px table row 29px). Instead the tag's first item is an empty
   line as tall as the tag, in the surrounding text's own font (the root
   sets no size, family or weight: the text part does), and the tag sits on
   the baseline: its baseline is then the one a centred line of that text
   has, in a mono table cell as in body text. With the tag's family on the
   root the empty line took the tag's metrics and the parent's line the
   parent's, and the two could round a pixel apart. The gap after it is
   taken back. */
.tag::before {
  content: '\200b';
  inline-size: 0;
  margin-inline-end: calc(var(--space-1) * -1);
  line-height: var(--control-xs);
}

.text {
  font-family: var(--font-sans);
  font-weight: 500;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  /* Lets a long text shrink and ellipsize once the tag hits max-inline-size. */
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.icon {
  display: inline-flex;
  flex-shrink: 0;
  font-size: var(--icon-xs);
}

.avatar {
  flex-shrink: 0;
  inline-size: var(--icon-xs);
  block-size: var(--icon-xs);
  border-radius: var(--radius-pill);
  object-fit: cover;
}

/* One rule per variant: the appearance rules below read these. Neutral
   reuses the secondary surface; the rest read --<name>, -foreground,
   -subtle and -text, which the token build measures at 4.5:1. */
.neutral {
  --tag-solid: var(--color-text);
  --tag-on-solid: var(--color-surface);
  --tag-subtle: var(--color-background-neutral);
  --tag-text: var(--color-text);
}

.info {
  --tag-solid: var(--color-background-info-bold);
  --tag-on-solid: var(--color-text-info-inverse);
  --tag-subtle: var(--color-background-info);
  --tag-text: var(--color-text-info);
}

.success {
  --tag-solid: var(--color-background-success-bold);
  --tag-on-solid: var(--color-text-success-inverse);
  --tag-subtle: var(--color-background-success);
  --tag-text: var(--color-text-success);
}

.warning {
  --tag-solid: var(--color-background-warning-bold);
  --tag-on-solid: var(--color-text-warning-inverse);
  --tag-subtle: var(--color-background-warning);
  --tag-text: var(--color-text-warning);
}

.danger {
  --tag-solid: var(--color-background-danger-bold);
  --tag-on-solid: var(--color-text-danger-inverse);
  --tag-subtle: var(--color-background-danger);
  --tag-text: var(--color-text-danger);
}

.red {
  --tag-solid: var(--color-background-accent-red-bolder);
  --tag-on-solid: var(--color-text-accent-red-inverse);
  --tag-subtle: var(--color-background-accent-red-subtler);
  --tag-text: var(--color-text-accent-red);
}

.orange {
  --tag-solid: var(--color-background-accent-orange-bolder);
  --tag-on-solid: var(--color-text-accent-orange-inverse);
  --tag-subtle: var(--color-background-accent-orange-subtler);
  --tag-text: var(--color-text-accent-orange);
}

.amber {
  --tag-solid: var(--color-background-accent-amber-bolder);
  --tag-on-solid: var(--color-text-accent-amber-inverse);
  --tag-subtle: var(--color-background-accent-amber-subtler);
  --tag-text: var(--color-text-accent-amber);
}

.yellow {
  --tag-solid: var(--color-background-accent-yellow-bolder);
  --tag-on-solid: var(--color-text-accent-yellow-inverse);
  --tag-subtle: var(--color-background-accent-yellow-subtler);
  --tag-text: var(--color-text-accent-yellow);
}

.lime {
  --tag-solid: var(--color-background-accent-lime-bolder);
  --tag-on-solid: var(--color-text-accent-lime-inverse);
  --tag-subtle: var(--color-background-accent-lime-subtler);
  --tag-text: var(--color-text-accent-lime);
}

.green {
  --tag-solid: var(--color-background-accent-green-bolder);
  --tag-on-solid: var(--color-text-accent-green-inverse);
  --tag-subtle: var(--color-background-accent-green-subtler);
  --tag-text: var(--color-text-accent-green);
}

.emerald {
  --tag-solid: var(--color-background-accent-emerald-bolder);
  --tag-on-solid: var(--color-text-accent-emerald-inverse);
  --tag-subtle: var(--color-background-accent-emerald-subtler);
  --tag-text: var(--color-text-accent-emerald);
}

.teal {
  --tag-solid: var(--color-background-accent-teal-bolder);
  --tag-on-solid: var(--color-text-accent-teal-inverse);
  --tag-subtle: var(--color-background-accent-teal-subtler);
  --tag-text: var(--color-text-accent-teal);
}

.cyan {
  --tag-solid: var(--color-background-accent-cyan-bolder);
  --tag-on-solid: var(--color-text-accent-cyan-inverse);
  --tag-subtle: var(--color-background-accent-cyan-subtler);
  --tag-text: var(--color-text-accent-cyan);
}

.sky {
  --tag-solid: var(--color-background-accent-sky-bolder);
  --tag-on-solid: var(--color-text-accent-sky-inverse);
  --tag-subtle: var(--color-background-accent-sky-subtler);
  --tag-text: var(--color-text-accent-sky);
}

.blue {
  --tag-solid: var(--color-background-accent-blue-bolder);
  --tag-on-solid: var(--color-text-accent-blue-inverse);
  --tag-subtle: var(--color-background-accent-blue-subtler);
  --tag-text: var(--color-text-accent-blue);
}

.indigo {
  --tag-solid: var(--color-background-accent-indigo-bolder);
  --tag-on-solid: var(--color-text-accent-indigo-inverse);
  --tag-subtle: var(--color-background-accent-indigo-subtler);
  --tag-text: var(--color-text-accent-indigo);
}

.violet {
  --tag-solid: var(--color-background-accent-violet-bolder);
  --tag-on-solid: var(--color-text-accent-violet-inverse);
  --tag-subtle: var(--color-background-accent-violet-subtler);
  --tag-text: var(--color-text-accent-violet);
}

.purple {
  --tag-solid: var(--color-background-accent-purple-bolder);
  --tag-on-solid: var(--color-text-accent-purple-inverse);
  --tag-subtle: var(--color-background-accent-purple-subtler);
  --tag-text: var(--color-text-accent-purple);
}

.fuchsia {
  --tag-solid: var(--color-background-accent-fuchsia-bolder);
  --tag-on-solid: var(--color-text-accent-fuchsia-inverse);
  --tag-subtle: var(--color-background-accent-fuchsia-subtler);
  --tag-text: var(--color-text-accent-fuchsia);
}

.pink {
  --tag-solid: var(--color-background-accent-pink-bolder);
  --tag-on-solid: var(--color-text-accent-pink-inverse);
  --tag-subtle: var(--color-background-accent-pink-subtler);
  --tag-text: var(--color-text-accent-pink);
}

.rose {
  --tag-solid: var(--color-background-accent-rose-bolder);
  --tag-on-solid: var(--color-text-accent-rose-inverse);
  --tag-subtle: var(--color-background-accent-rose-subtler);
  --tag-text: var(--color-text-accent-rose);
}

.subtle {
  background: var(--tag-subtle);
  color: var(--tag-text);
}

.outlined {
  border-color: var(--tag-text);
  color: var(--tag-text);
}

.solid {
  background: var(--tag-solid);
  color: var(--tag-on-solid);
}

.remove {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  margin: 0;
  padding: 0;
  border: 0;
  /* 2px: the button is a 12px mark, smaller than a control. */
  border-radius: max(var(--radius-xs), var(--radius-full));
  background: transparent;
  color: inherit;
  font-size: var(--icon-xs);
  cursor: var(--cursor-button);
}

/* A tint of whatever colour the tag's text is, so hover reads on every
   variant and appearance without a token per combination. */
.remove:hover {
  background: color-mix(in oklch, currentColor 15%, transparent);
}

/* Same ring as every control, hugging the 12px mark: inset it would cover
   the glyph, and 2px out it still sits inside the 20px tag. */
.remove:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: 0;
}

/* The visible button is 12px; its hit area is 24px (WCAG 2.5.8), and 44px
   on touch screens, without the tag growing with it. */
.remove::before {
  content: '';
  position: absolute;
  inset: 50% auto auto 50%;
  inline-size: var(--box-sm);
  block-size: var(--box-sm);
  translate: -50% -50%;
}
@media (pointer: coarse) {
  .remove::before {
    inline-size: var(--target-coarse);
    block-size: var(--target-coarse);
  }
}
